    { const char * tb_v1578 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v1578; }
    { const char * tb_v1579 = "    if (d->slots && !(tb_nchunks > 0 && tb_in_temp(d->slots))) free(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v1579; }
