    { const char * tb_v1600 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1600; }
    { const char * tb_v1601 = "        tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v1601; }
