    { const char * tb_v1725 = "static void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1725; }
    { const char * tb_v1726 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v1726; }
