    { const char * tb_v1740 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1740; }
    { const char * tb_v1741 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1741; }
